INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('583ef152-7652-453c-8928-55446e619655','9','geografie-fizica','published',2,101,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('583ef152-7652-453c-8928-55446e619655','ro','Ce pune în mișcare plăcile tectonice, făcându-le să se deplaseze lent pe astenosferă?','["Rotația Pământului în jurul axei sale.","Atracția Lunii asupra scoarței terestre.","Curenții de convecție din manta: materia caldă urcă, cea răcită coboară.","Vânturile puternice care bat la suprafața Pământului."]','Gândește-te ce se mișcă în adânc, sub plăci, nu deasupra lor. Buclele de convecție din manta transportă căldură și „târăsc" plăcile de deasupra, ca pe niște plute pe un lichid care fierbe încet.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('f101c547-622c-4dec-b3ad-bb23fda8d593','9','geografie-fizica','published',1,102,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('f101c547-622c-4dec-b3ad-bb23fda8d593','ro','La un contact divergent, două plăci se depărtează una de alta. Ce se întâmplă în spațiul care se deschide între ele?','["Se formează imediat o fosă adâncă prin scufundare.","Urcă magmă care se solidifică și creează scoarță nouă.","Se ridică pe loc un lanț de munți continentali.","Nu se întâmplă nimic; rămâne un gol în litosferă."]','Dacă placa se rupe și se desface, ceva trebuie să umple golul de jos. Magma urcă în crăpătură, se răcește și formează scoarță nouă — de aceea la rifturi și dorsale se „naște" litosferă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('fa362935-39c6-475c-949d-2b05f4a260ca','9','geografie-fizica','published',0,103,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('fa362935-39c6-475c-949d-2b05f4a260ca','ro','Când o placă oceanică se ciocnește cu una continentală, placa oceanică alunecă pe dedesubt (subducție). De ce tocmai ea coboară?','["Pentru că scoarța oceanică este mai densă decât cea continentală.","Pentru că scoarța oceanică este mult mai groasă.","Pentru că scoarța oceanică este mai caldă.","Pentru că scoarța oceanică se deplasează mai încet."]','Când două lucruri se ciocnesc, cel mai greu (mai dens) tinde să meargă în jos. Scoarța oceanică, mai densă, se scufundă sub cea continentală, mai ușoară, și formează o fosă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('71656c22-21d5-4fac-8a88-ed4388e1722c','9','geografie-fizica','published',3,104,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('71656c22-21d5-4fac-8a88-ed4388e1722c','ro','Munții Himalaya continuă să se înalțe și astăzi. Care tip de contact tectonic explică cel mai bine formarea lor?','["Divergența a două plăci oceanice.","Alunecarea laterală a plăcilor (contact transformant).","Un punct fierbinte (hot-spot) din interiorul unei plăci.","Coliziunea a două plăci continentale, ale căror margini se încrețesc."]','Munți foarte înalți apar acolo unde scoarța este împinsă și îngrămădită. Ciocnirea a două plăci continentale nu permite subducția, așa că marginile se cutează și se ridică în munți precum Himalaya.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0ad6c8af-2127-4db8-9924-9aee631d5191','9','geografie-fizica','published',1,105,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0ad6c8af-2127-4db8-9924-9aee631d5191','ro','Insulele Hawaii formează un șir, cu vulcani tot mai vechi într-o direcție și tot mai noi în cealaltă. Cum explică vulcanismul de tip hot-spot acest lucru?','["Punctul fierbinte se mișcă, iar placa stă pe loc.","Placa se deplasează deasupra unui punct fierbinte fix, care străpunge pe rând scoarța și formează insule noi.","Toate insulele au erupt exact în același moment.","Insulele au fost aduse una lângă alta de curenții oceanici."]','Imaginează-ți o coală de hârtie trasă încet peste o lumânare aprinsă: arsurile se înșiră. Placa alunecă peste punctul fierbinte fix, iar vulcanii apar unul după altul, formând un lanț de insule.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('251a2213-6745-4ea5-b054-4f3931321f22','9','geografie-fizica','published',2,106,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('251a2213-6745-4ea5-b054-4f3931321f22','ro','Un cutremur cu aceeași magnitudine produce, în două orașe diferite, pagube foarte diferite. Care scară descrie tocmai această diferență de efecte?','["Scara Richter, calculată separat pentru fiecare oraș.","Adâncimea hipocentrului, exprimată în kilometri.","Scara Mercalli, care măsoară intensitatea, adică efectele resimțite.","Scara de proporție folosită la hărți."]','Magnitudinea (Richter) este o singură valoare pentru tot cutremurul; efectele diferă de la loc la loc. Tocmai aceste efecte le măsoară scara Mercalli — intensitatea resimțită în fiecare loc.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9f64dd36-65c7-4948-85b1-a96773fd0f3d','9','geografie-fizica','published',0,107,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9f64dd36-65c7-4948-85b1-a96773fd0f3d','ro','Care este deosebirea dintre hipocentru și epicentru la un cutremur?','["Hipocentrul este locul din adânc unde se produce ruptura, iar epicentrul este punctul de la suprafață aflat exact deasupra lui.","Sunt același lucru, numit în două feluri.","Epicentrul este mai adânc decât hipocentrul.","Hipocentrul se află întotdeauna în ocean."]','Prefixul „hipo" trimite spre adânc, iar „epi" spre suprafață. Hipocentrul (focarul) este în adânc, unde se rupe scoarța; epicentrul este proiecția lui la suprafață, unde se simte cel mai tare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('32d56f7b-459e-45e2-8928-4f6a1a3960fe','9','geografie-fizica','published',3,108,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('32d56f7b-459e-45e2-8928-4f6a1a3960fe','ro','O mișcare epirogenetică pozitivă ridică lent uscatul. Ce fenomen o însoțește, de obicei, la țărm?','["O transgresiune marină: marea înaintează peste uscat.","O erupție vulcanică puternică.","Un cutremur de foarte mare adâncime.","O regresiune marină: linia țărmului se retrage spre larg."]','Dacă uscatul urcă, apa „rămâne în urmă" și se retrage. Ridicarea uscatului (mișcare pozitivă) duce la o regresiune — marea se retrage; coborârea ar aduce o transgresiune.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('cb9fd682-cc1a-4656-9091-09b4ad60a84d','9','geografie-fizica','published',1,109,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('cb9fd682-cc1a-4656-9091-09b4ad60a84d','ro','De ce lava bogată în siliciu (acidă) dă erupții explozive, iar cea săracă în siliciu (bazică) erupții liniștite?','["Pentru că lava acidă este mai rece și mai grea decât aerul.","Pentru că lava acidă este vâscoasă, curge greu și blochează coșul, iar gazele acumulează presiune până la explozie.","Pentru că lava bazică conține mult mai mult siliciu.","Pentru că lava bazică nu conține deloc gaze."]','Leagă vâscozitatea de felul cum scapă gazele. O lavă vâscoasă (acidă) astupă coșul, gazele nu ies ușor și presiunea crește până erupe exploziv; lava fluidă (bazică) lasă gazele să scape lin.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9d303caf-777e-4697-a323-09113d575cf2','9','geografie-fizica','published',2,110,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9d303caf-777e-4697-a323-09113d575cf2','ro','La aceeași stație seismică sosesc întâi undele principale (P) și abia apoi undele secundare (S). Ce putem deduce corect?','["Undele S pornesc din focar mai târziu decât undele P.","Undele P și undele S sunt, de fapt, identice.","Undele P se propagă mai repede decât undele S.","Undele S nu ajung niciodată la suprafață."]','Amândouă pornesc în același moment din focar; dacă una sosește prima, înseamnă că merge mai repede. Undele principale (P) sunt cele mai rapide, de aceea ajung înaintea celor secundare (S).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('eecf87f4-1eab-42eb-b9f8-17d1f19e59b5','9','geografie-fizica','published',0,111,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('eecf87f4-1eab-42eb-b9f8-17d1f19e59b5','ro','Studiind cum își schimbă viteza și direcția undele seismice în adâncime, cercetătorii au descoperit discontinuitățile din interiorul Pământului. Ce arată acest lucru?','["Că undele seismice sunt un instrument de „radiografiere” a interiorului planetei.","Că interiorul Pământului este complet gol.","Că undele seismice nu au nicio legătură cu structura internă.","Că toate discontinuitățile se află la suprafață."]','Nu putem săpa până în centrul Pământului, dar undele pot. Fiindcă ele își schimbă comportamentul la trecerea dintr-un înveliș în altul, urmărirea lor dezvăluie structura internă a planetei.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('8c0ec176-47dd-441c-8278-da494f07d53a','9','geografie-fizica','published',1,112,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('8c0ec176-47dd-441c-8278-da494f07d53a','ro','Fosile ale acelorași plante și animale se găsesc pe continente aflate azi de o parte și de alta a oceanelor. Care ipoteză explică cel mai bine acest fapt?','["Speciile au traversat oceanele înot sau în zbor.","Continentele au fost cândva unite (Pangaea) și apoi s-au îndepărtat unele de altele.","Fosilele au fost transportate peste oceane de vânt.","Continentele au stat dintotdeauna exact în pozițiile actuale."]','Dacă aceleași viețuitoare trăiau pe uscaturi azi separate, cel mai simplu este că uscaturile erau lipite atunci. Continentele formau un supercontinent (Pangaea) care s-a fragmentat, iar bucățile s-au depărtat.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a142283f-31ed-4efa-aa78-7cb4e19d7ac3','9','geografie-fizica','published',3,113,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a142283f-31ed-4efa-aa78-7cb4e19d7ac3','ro','Care este cea mai adâncă formă a reliefului oceanic și în ce zonă tectonică se formează?','["Platforma continentală, la contactele divergente.","Câmpia abisală, chiar în mijlocul oceanului.","Dorsala, la marginea continentelor.","Fosa oceanică, în zonele de subducție."]','Cel mai adânc loc apare acolo unde o placă se afundă sub alta. La subducție, marginea plăcii care coboară trage în jos fundul oceanic și creează fosa — cea mai adâncă formă a reliefului oceanic.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('458f1832-f728-41a8-bcdf-edc081bd16c5','9','geografie-fizica','published',2,114,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('458f1832-f728-41a8-bcdf-edc081bd16c5','ro','În România, mișcarea de ansamblu a plăcilor pare a fi încetat (munții nu se mai înalță, vulcanii nu mai erup), totuși în Vrancea se produc cutremure puternice, la mare adâncime. Care este explicația probabilă?','["Cutremurele sunt provocate de vânturile puternice de la suprafață.","În realitate, munții din zonă continuă să se înalțe rapid.","Un fragment de placă coboară independent spre astenosferă și eliberează energie la adâncime.","Cutremurele sunt resimțite doar pentru că vin din alte țări."]','Faptul că vulcanii tac și munții nu mai cresc arată că dinamica de suprafață a încetat, dar energia vine de dedesubt. Un fragment de placă ce se scufundă independent explică seismele adânci din Vrancea.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('5b4596f3-3a7d-484f-a4d4-a8b678d3aa8e','9','geografie-fizica','published',0,115,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('5b4596f3-3a7d-484f-a4d4-a8b678d3aa8e','ro','Mofetele sunt emanații reci de dioxid de carbon (CO₂) legate de vulcanism. Ce resursă folositoare rezultă când acest CO₂ se dizolvă în apele subterane?','["Apele minerale carbogazoase.","Zăcămintele de petrol.","Straturile de cărbune.","Sarea gemă."]','Gândește-te ce obții când amesteci CO₂ cu apă (ca la o băutură acidulată). CO₂-ul mofetelor, dizolvat în apele subterane, dă naștere apelor minerale carbogazoase.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('20b9e986-5cec-4cfb-a845-9baea6874b6f','9','geografie-fizica','published',1,116,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('20b9e986-5cec-4cfb-a845-9baea6874b6f','ro','Prin ce se deosebește magmatismul de vulcanism, în privința locului unde se consolidează magma?','["La magmatism magma se revarsă la suprafață ca lavă.","La magmatism magma se răcește și se consolidează în interiorul scoarței, formând corpuri magmatice (de exemplu batolite).","La magmatism magma se transformă în cenușă în atmosferă.","La magmatism magma se depune pe fundul oceanului ca sedimente."]','Cheia este cuvântul „în interiorul scoarței". La vulcanism magma iese afară (lavă), la magmatism ea rămâne captivă în scoarță, unde se răcește lent și formează corpuri magmatice.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('271bd306-e61a-4f0c-abdd-5c1dabcd02df','9','geografie-fizica','published',2,117,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('271bd306-e61a-4f0c-abdd-5c1dabcd02df','ro','De ce este firesc ca majoritatea vulcanilor și cutremurelor să se concentreze pe Cercul de Foc al Pacificului?','["Pentru că acolo este cel mai cald climat de pe Glob.","Pentru că Pacificul este cel mai mic ocean.","Pentru că acolo se întâlnesc numeroase margini de plăci, mai ales zone de subducție.","Pentru că în Pacific nu există deloc plăci tectonice."]','Vulcanii și cutremurele apar la marginile plăcilor, nu la mijlocul lor. Placa Pacifică este înconjurată de multe zone de subducție, de aceea în jurul ei se aglomerează vulcanii și seismele.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c13e2d37-3d0f-4973-ad87-dbed155f0d5b','9','geografie-fizica','published',3,118,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c13e2d37-3d0f-4973-ad87-dbed155f0d5b','ro','Ce au în comun dorsalele oceanice și zonele de rift continental (precum riftul est-african)?','["Ambele sunt zone de subducție, unde o placă coboară.","Ambele sunt cele mai adânci fose ale oceanelor.","În ambele plăcile se apropie și se ciocnesc.","În ambele plăcile se depărtează, iar între ele se creează scoarță nouă."]','Uită-te la sensul mișcării plăcilor în ambele cazuri. Și dorsala, și riftul continental sunt contacte divergente: plăcile se desfac, iar magma care urcă formează scoarță nouă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('eb436114-166b-495a-aac7-59d6a2cde6ec','9','geografie-fizica','published',1,119,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('eb436114-166b-495a-aac7-59d6a2cde6ec','ro','Scoarța continentală are trei pături (bazaltică, granitică și sedimentară), iar scoarța oceanică practic una singură. Care este aceasta?','["Doar pătura granitică.","Doar pătura bazaltică.","Doar pătura sedimentară.","Toate trei păturile, la fel ca scoarța continentală."]','Reține că pătura granitică lipsește sub oceane. Scoarța oceanică, mai subțire și mai densă, este alcătuită în esență din pătura bazaltică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('ecd4b1dd-0a7f-4226-920d-3cec4a6d055b','9','geografie-fizica','published',0,120,1783300000000,1783300000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('ecd4b1dd-0a7f-4226-920d-3cec4a6d055b','ro','Orogeneza alpină este cea mai recentă mare mișcare de formare a munților. Care lanț muntos i se datorează?','["Munții Carpați (împreună cu Alpii și Himalaya).","Munții Scoției (Grampiani).","Munții Ural.","Nordul Munților Appalachi."]','Asociază fiecare orogeneză cu munții ei: caledonică — Scoția/Scandinavia; hercinică — Uralul; alpină — cea mai nouă. Carpații, Alpii și Himalaya s-au format în orogeneza alpină.');
